/*
 * kinetigor-game — CHALLENGE ENGINE (JUDGE boundary)
 * judge(challenge, evidence) -> {verdict, reason_code, observed}
 *
 * Judges are deterministic pure functions of (challenge data, evidence,
 * run context). The UI can NEVER grant victory: every verdict is computed
 * here from the artifact bytes, never from what the player or the
 * interface claims. Verdict algebra (Athelgard kernel):
 *   PASS | FAIL | REFUSE | QUARANTINE   (QUARANTINE > REFUSE > FAIL > PASS)
 *
 * Stage fixtures for stages 2-4 are generated by cli/make-fixtures.js
 * into www/fixtures.js (KIN.FIXTURES) — one source, no duplication.
 *
 * Zero dependencies. Node >= 16 and browsers.
 */
(function (root) {
  "use strict";
  if (typeof require === "function") {
    if (!root.KIN || !root.KIN.Trust) require("./trust.js");
    if (!root.KIN || !root.KIN.Kernel) require("./kernel.js");
    if (!root.KIN || !root.KIN.Validator) require("./validator.js");
  }

  var T = root.KIN.Trust;
  var V = root.KIN.Validator;
  var K = root.KIN.Kernel;

  function sha(s) { return T.sha256hex(s); }
  function canonDigest(v) { return sha(T.canon(v)); }

  function fail(m) { throw new Error("challenge engine: " + m); }

  function needFixtures(ctx) {
    if (!ctx || !ctx.fixtures) fail("fixtures unavailable — regenerate with: node cli/make-fixtures.js");
    return ctx.fixtures;
  }

  function isStr(x) { return typeof x === "string" && x.length > 0; }

  /* ============ STAGE 0 — ARRIVAL : the commission warrant ============ */

  var warrantRecords = [
    { record_id: "WRNT-2077-A17", fields: { clearance: "C-2", circuit: "Princetown Packet", name: "the arriving Verifier" } },
    { record_id: "WRNT-2077-A18", fields: { clearance: "C-1", circuit: "Princetown Packet", name: "Depot Manifest" } },
    { record_id: "WRNT-2077-A19", fields: { clearance: "C-3", circuit: "Princetown Packet", name: "Rally Standing Orders" } }
  ];
  warrantRecords.forEach(function (r) { r.digest = canonDigest(r.fields); });
  var TARGET_RECORD = "WRNT-2077-A17";

  function judgeArrival(ev) {
    if (!ev || !isStr(ev.record_id) || !isStr(ev.digest)) {
      return { verdict: "REFUSE", reason_code: "S0_MALFORMED", observed: "evidence must be {record_id, digest}" };
    }
    var rec = null;
    for (var i = 0; i < warrantRecords.length; i++) {
      if (warrantRecords[i].record_id === ev.record_id) rec = warrantRecords[i];
    }
    if (!rec) return { verdict: "FAIL", reason_code: "S0_UNKNOWN_RECORD", observed: "no such record in the warrant" };
    var actual = canonDigest(rec.fields);
    if (ev.record_id !== TARGET_RECORD) {
      return { verdict: "FAIL", reason_code: "S0_WRONG_RECORD", observed: "record verified, but the Arrival desk asks for " + TARGET_RECORD };
    }
    if (ev.digest !== actual) {
      return { verdict: "FAIL", reason_code: "S0_DIGEST_MISMATCH", observed: "submitted digest does not match the recomputed canonical bytes of " + ev.record_id };
    }
    return { verdict: "PASS", reason_code: "S0_VERIFIED", observed: "recomputed digest of " + ev.record_id + " matches its warrant entry" };
  }

  /* ============ STAGE 1 — POSTBRIDGE : the amended waybill ============ */

  var waybills = [
    { record_id: "PB-77-001", fields: { cargo: "sealed mail packet", route: "Princetown -> Postbridge", sealed_at: "2077-03-14T08:10:00Z" } },
    { record_id: "PB-77-002", fields: { cargo: "relay coin box", route: "Princetown -> Postbridge", sealed_at: "2077-03-14T08:25:00Z" } },
    { record_id: "PB-77-003", fields: { cargo: "weather report satchel", route: "Postbridge -> Two Bridges", sealed_at: "2077-03-14T09:05:00Z" } },
    { record_id: "PB-77-004", fields: { cargo: "sealed mail packet", route: "Postbridge -> Two Bridges", sealed_at: "2077-03-14T11:55:00Z" } },
    { record_id: "PB-77-005", fields: { cargo: "farrier's ledger", route: "Postbridge -> Dunnabridge", sealed_at: "2077-03-14T12:40:00Z" } },
    { record_id: "PB-77-006", fields: { cargo: "course lantern oil", route: "Postbridge -> Crockern", sealed_at: "2077-03-14T13:15:00Z" } }
  ];
  waybills.forEach(function (r) { r.digest = canonDigest(r.fields); });
  /* PB-77-004 was amended after sealing: its recorded seal commits the
   * ORIGINAL content (sealed 09:40), while its words now say 11:55. */
  waybills[3].digest = canonDigest({ cargo: "sealed mail packet", route: "Postbridge -> Two Bridges", sealed_at: "2077-03-14T09:40:00Z" });

  function mismatchingWaybills() {
    return waybills.filter(function (r) { return r.digest !== canonDigest(r.fields); });
  }
  if (mismatchingWaybills().length !== 1 || mismatchingWaybills()[0].record_id !== "PB-77-004") {
    fail("postbridge data integrity: expected exactly one amended waybill (PB-77-004)");
  }

  function judgePostbridge(ev) {
    if (!ev || !isStr(ev.record_id) || !isStr(ev.recomputed_digest)) {
      return { verdict: "REFUSE", reason_code: "PB_MALFORMED", observed: "evidence must be {record_id, recomputed_digest}" };
    }
    var rec = null;
    for (var i = 0; i < waybills.length; i++) {
      if (waybills[i].record_id === ev.record_id) rec = waybills[i];
    }
    if (!rec) return { verdict: "FAIL", reason_code: "PB_UNKNOWN_RECORD", observed: "no such waybill in the relay ledger" };
    var mismatch = mismatchingWaybills()[0];
    if (rec.record_id !== mismatch.record_id) {
      return { verdict: "FAIL", reason_code: "PB_SEAL_INTACT", observed: ev.record_id + " still matches its seal — the amendment is elsewhere" };
    }
    var actual = canonDigest(rec.fields);
    if (ev.recomputed_digest !== actual) {
      return { verdict: "FAIL", reason_code: "PB_DIGEST_MISMATCH", observed: "you found the right waybill, but the submitted digest is not the recomputed one" };
    }
    return { verdict: "PASS", reason_code: "PB_AMENDMENT_FOUND", observed: "PB-77-004 recomputes to " + actual.slice(0, 16) + "… but its recorded seal commits the 09:40 original — amended after sealing" };
  }

  /* ============ STAGE 2 — CACHE : the broken chain ============ */

  function judgeCache(ev, ctx) {
    var F = needFixtures(ctx);
    if (!ev || !isStr(ev.first_bad_receipt_id) || !isStr(ev.reason_code) || !isStr(ev.last_valid_receipt_id)) {
      return { verdict: "REFUSE", reason_code: "CACHE_MALFORMED", observed: "a quarantine order must name {first_bad_receipt_id, reason_code, last_valid_receipt_id}" };
    }
    var rep = V.validateChain(F.cache_chain.chain, {});
    var bad = null, lastValid = null;
    for (var i = 0; i < rep.reasons.length; i++) {
      var r = rep.reasons[i];
      if (r.codes.indexOf("INVALID_HASH") !== -1 && bad === null) { bad = r; }
    }
    if (!bad) return { verdict: "FAIL", reason_code: "CACHE_NO_BREAK_FOUND", observed: "the cache chain walks clean — no quarantine is warranted" };
    var seq = bad.seq;
    if (seq > 0 && rep.reasons.every(function (x) { return x.seq !== seq - 1; })) {
      lastValid = F.cache_chain.chain[seq - 1].receipt_id;
    }
    if (ev.first_bad_receipt_id !== bad.receipt_id) {
      return { verdict: "FAIL", reason_code: "CACHE_WRONG_FIRST_BAD", observed: "the first receipt where the cache stops proving its claims is elsewhere" };
    }
    if (ev.reason_code !== "INVALID_HASH") {
      return { verdict: "FAIL", reason_code: "CACHE_WRONG_REASON", observed: "re-walking the chain shows the failure class at " + bad.receipt_id + " is a hash break" };
    }
    if (ev.last_valid_receipt_id !== lastValid) {
      return { verdict: "FAIL", reason_code: "CACHE_WRONG_LAST_VALID", observed: "the last receipt still proved by the cache is not the one named" };
    }
    return { verdict: "PASS", reason_code: "CACHE_QUARANTINE_ACCEPTED", observed: "cache quarantined at " + bad.receipt_id + " (" + bad.codes.join(", ") + "); last valid state: " + lastValid };
  }

  /* ============ STAGE 3 — DELIVERY : content is not provenance ============ */

  function packetVerdicts(F) {
    return F.delivery_packets.map(function (p) {
      var chainOk = V.validateChain(p.chain, {}).valid;
      var contentDigest = canonDigest(p.content);
      var contentOk = contentDigest === p.committed_digest;
      return { packet: p, chainOk: chainOk, contentOk: contentOk, ok: chainOk && contentOk };
    });
  }

  function judgeDelivery(ev, ctx) {
    var F = needFixtures(ctx);
    if (!ev || !isStr(ev.packet_id) || !isStr(ev.authority_receipt)) {
      return { verdict: "REFUSE", reason_code: "DLV_MALFORMED", observed: "evidence must be {packet_id, authority_receipt}" };
    }
    /* operational relevance of earlier receipts: the delivery desk accepts
     * a choice only from a Verifier whose OWN chain carries the cache
     * quarantine receipt (a PASS from stage 2). */
    var authOk = false;
    for (var a = 0; a < ctx.receipts.length; a++) {
      var rc = ctx.receipts[a];
      if (rc.receipt_id === ev.authority_receipt && rc.game.challenge_id === "cache-02" && rc.game.verdict === "PASS") authOk = true;
    }
    if (!authOk) {
      return { verdict: "FAIL", reason_code: "DLV_NO_AUTHORITY", observed: "no PASS receipt from the cache desk carries that id — the delivery desk cannot act without your own quarantine authority" };
    }
    var verdicts = packetVerdicts(F);
    var chosen = null;
    for (var i = 0; i < verdicts.length; i++) {
      if (verdicts[i].packet.packet_id === ev.packet_id) chosen = verdicts[i];
    }
    if (!chosen) return { verdict: "FAIL", reason_code: "DLV_UNKNOWN_PACKET", observed: "no such packet on the delivery bench" };
    var good = verdicts.filter(function (v) { return v.ok; });
    if (good.length !== 1) fail("delivery fixture integrity: expected exactly one acceptable packet");
    if (!chosen.ok) {
      if (chosen.chainOk && !chosen.contentOk) {
        return { verdict: "FAIL", reason_code: "DLV_CONTENT_IS_NOT_PROVENANCE", observed: "that packet's chain is intact, but it never committed THIS content — content is not provenance" };
      }
      return { verdict: "FAIL", reason_code: "DLV_BROKEN_CHAIN", observed: "that packet's chain does not survive a walk under the frozen contract" };
    }
    return { verdict: "PASS", reason_code: "DLV_PROVENANCE_ACCEPTED", observed: "packet " + chosen.packet.packet_id + " accepted: chain valid and content committed by it (digest " + canonDigest(chosen.packet.content).slice(0, 16) + "…)" };
  }

  /* ============ STAGE 4 — APEX : the dispatch under five checks ============ */

  function judgeApex(ev, ctx) {
    var F = needFixtures(ctx);
    if (!ev || !isStr(ev.quarantine_record) || !Array.isArray(ev.liar_records) || !isStr(ev.deliverable_record)) {
      return { verdict: "REFUSE", reason_code: "APEX_MALFORMED", observed: "the apex submission must name {quarantine_record, liar_records[], deliverable_record}" };
    }
    var results = K.verifyRecords(F.apex_bundle);
    var quarantined = [], liars = [], deliverable = [];
    results.forEach(function (r) {
      if (r.verdict === "QUARANTINE") quarantined.push(r.record_id);
      if (r.claimed_status === "PASS" && r.verdict === "FAIL") liars.push(r.record_id);
      if (r.verdict === "PASS") deliverable.push(r.record_id);
    });
    liars.sort();
    ev.liar_records.sort();
    if (quarantined.length !== 1 || deliverable.length !== 1) {
      fail("apex fixture integrity: expected exactly one quarantine and one deliverable");
    }
    var notes = [];
    if (ev.quarantine_record !== quarantined[0]) {
      return { verdict: "FAIL", reason_code: "APEX_WRONG_QUARANTINE", observed: "the five checks quarantine a different record — re-run them and watch the nonce" };
    }
    if (JSON.stringify(ev.liar_records) !== JSON.stringify(liars)) {
      return { verdict: "FAIL", reason_code: "APEX_WRONG_LIARS", observed: "the liar set differs — a narrator's claim matters only when the checks refute it" };
    }
    if (ev.deliverable_record !== deliverable[0]) {
      return { verdict: "FAIL", reason_code: "APEX_WRONG_DELIVERABLE", observed: "the only record surviving all five checks is another one" };
    }
    notes.push("quarantined " + quarantined[0] + "; liars " + liars.join(", ") + "; deliverable " + deliverable[0]);
    return { verdict: "PASS", reason_code: "APEX_SEALED", observed: "dispatch sealed: " + notes.join("; ") };
  }

  /* ============ the run (stage order is part of the contract) ============ */

  var CHALLENGES = [
    {
      id: "arrival-00", version: "1.0.0", station: "STAGE 0 — ARRIVAL",
      title: "The Commission Warrant",
      brief: "You arrive at the Rally depot holding a commission warrant. The depot does not greet you by face — it greets you by digest. Every warrant record carries an integrity digest: a seal computed over the record's canonical bytes.",
      objective: "Verify your own commission: recompute the digest of record WRNT-2077-A17 and submit {record_id, digest}. The lens tool computes canonical bytes and SHA-256 for you — the judge recomputes everything itself and never trusts the lens.",
      evidence_fields: [
        { key: "record_id", label: "record id", placeholder: "WRNT-2077-A17" },
        { key: "digest", label: "recomputed digest", placeholder: "64 hex chars" }
      ],
      claim: {
        statement: "The commission warrant record WRNT-2077-A17 carries an integrity digest that matches its own canonical bytes.",
        falsifier: "Recomputing sha256 over the canonical record fields yields a digest different from the warrant entry."
      },
      gate: "arrival-00/digest-recompute",
      expected: "submitted digest equals sha256 of the canonical WRNT-2077-A17 record fields",
      artifact: function () { return { kind: "records", title: "Commission Warrant", records: warrantRecords }; },
      judge: judgeArrival
    },
    {
      id: "postbridge-01", version: "1.0.0", station: "STAGE 1 — POSTBRIDGE",
      title: "The Amended Waybill",
      brief: "Postbridge keeps a relay ledger. Each waybill was sealed at posting: its recorded digest commits the words exactly as they were. One waybill's words no longer match the seal recorded for it — someone amended a record after it was sealed.",
      objective: "Find the amended waybill. Submit {record_id, recomputed_digest}: the waybill whose recomputed digest contradicts its recorded seal, and the digest you recomputed from its current words.",
      evidence_fields: [
        { key: "record_id", label: "waybill id", placeholder: "PB-77-0nn" },
        { key: "recomputed_digest", label: "recomputed digest (current words)", placeholder: "64 hex chars" }
      ],
      claim: {
        statement: "Postbridge waybill PB-77-004 no longer matches the seal recorded for it.",
        falsifier: "Recomputing the digest of PB-77-004's canonical content reproduces its recorded seal."
      },
      gate: "postbridge-01/seal-mismatch",
      expected: "the submitted record is the unique waybill whose recomputed digest mismatches its recorded seal, and the submitted digest equals the recomputed one",
      artifact: function () { return { kind: "records", title: "Postbridge Relay Ledger", records: waybills }; },
      judge: judgePostbridge
    },
    {
      id: "cache-02", version: "1.0.0", station: "STAGE 2 — CACHE",
      title: "The Cache That Lies",
      brief: "The depot cache holds a recovered receipt chain — six judgments from a run before yours. Walk it with the contract: each receipt's hash must cover its payload and its predecessor. Somewhere the cache stops proving its claims, and everything after that point is cascade, not proof. Do not just find corruption: find where trust last stood.",
      objective: "File a quarantine order: submit {first_bad_receipt_id, reason_code, last_valid_receipt_id} — the FIRST receipt that fails, the contract reason code for the failure class, and the last receipt the chain still proves.",
      evidence_fields: [
        { key: "first_bad_receipt_id", label: "first bad receipt id", placeholder: "rcpt-…" },
        { key: "reason_code", label: "reason code", placeholder: "INVALID_HASH" },
        { key: "last_valid_receipt_id", label: "last valid receipt id", placeholder: "rcpt-…" }
      ],
      claim: {
        statement: "The depot cache chain first ceases to prove its claims at a specific receipt, identifiable by re-walking the chain under the frozen contract.",
        falsifier: "Walking the cache chain with the frozen contract places the first integrity failure elsewhere."
      },
      gate: "cache-02/chain-walk",
      expected: "first-bad receipt, reason code and last-valid receipt match a fresh validator walk of the cache chain",
      artifact: function () { return { kind: "chain", title: "Depot Cache Log", meta: "cache_chain" }; },
      judge: judgeCache
    },
    {
      id: "delivery-03", version: "1.0.0", station: "STAGE 3 — DELIVERY",
      title: "Content Is Not Provenance",
      brief: "Three packets wait on the delivery bench, each with content and a provenance chain. Any of them can tell a plausible story; only provenance can carry one across the moor. A packet is acceptable only if its chain survives a full walk AND the chain's committed digest is the digest of the content actually in the crate.",
      objective: "Choose the one packet whose provenance carries its content. Submit {packet_id, authority_receipt} — authority_receipt is the receipt id of YOUR OWN accepted quarantine order from the Cache desk.",
      evidence_fields: [
        { key: "packet_id", label: "packet id", placeholder: "PKT-X" },
        { key: "authority_receipt", label: "your cache PASS receipt id", placeholder: "rcpt-…" }
      ],
      claim: {
        statement: "Exactly one delivery packet is both internally chained and committed by its chain to the content it presents.",
        falsifier: "Walking each packet's chain and recomputing each content digest accepts a different packet, or more than one."
      },
      gate: "delivery-03/provenance-carries",
      expected: "the chosen packet's chain validates and its content digest matches the chain's commitment, and the cited authority receipt is this run's cache PASS receipt",
      artifact: function () { return { kind: "packets", title: "Delivery Bench", meta: "delivery_packets" }; },
      judge: judgeDelivery
    },
    {
      id: "apex-04", version: "1.0.0", station: "STAGE 4 — APEX",
      title: "The Apex Dispatch",
      brief: "The final dispatch: five records, each narrating its own status. Narration is not evidence. Run the five checks on every record — IDENTITY, PROVENANCE, SEQUENCE, UNIQUENESS, ATOMICITY — and let the checks, not the narrators, decide. One record must be quarantined. Some narrators claim PASS where the checks say otherwise. Exactly one record survives everything.",
      objective: "Submit {quarantine_record, liar_records: [...], deliverable_record} — the record the checks quarantine (a quarantined record claims a status too; the claim changes nothing), the records whose claimed_status says PASS but whose checks fail, and the one record that survives all five checks.",
      evidence_fields: [
        { key: "quarantine_record", label: "record to quarantine", placeholder: "DX-2nn" },
        { key: "liar_records", label: "liar records (JSON array)", placeholder: "[\"DX-2nn\"]" },
        { key: "deliverable_record", label: "the deliverable", placeholder: "DX-2nn" }
      ],
      claim: {
        statement: "The apex dispatch contains exactly one record that survives all five checks, one that must be quarantined, and narrators whose claims the checks refute.",
        falsifier: "Running the five checks on the dispatch yields a different quarantine, liar set, or deliverable."
      },
      gate: "apex-04/five-checks",
      expected: "quarantine, liar set and deliverable match a fresh five-check run over the dispatch records",
      artifact: function () { return { kind: "dispatch", title: "Apex Dispatch Bundle", meta: "apex_bundle" }; },
      judge: judgeApex
    }
  ];

  var ORDER = CHALLENGES.map(function (c) { return c.id; });

  var api = {
    ORDER: ORDER,
    CHALLENGES: CHALLENGES,
    byId: function (id) {
      for (var i = 0; i < CHALLENGES.length; i++) if (CHALLENGES[i].id === id) return CHALLENGES[i];
      return null;
    },
    /* exposed for tests only */
    _internals: { warrantRecords: warrantRecords, waybills: waybills, mismatchingWaybills: mismatchingWaybills }
  };

  root.KIN = root.KIN || {};
  root.KIN.Challenges = api;
  if (typeof module !== "undefined" && module.exports) module.exports = api;
})(typeof globalThis !== "undefined" ? globalThis : this);
